sys_script_include.script:
var CreateOnPremIntegrationTasks = Class.create();
CreateOnPremIntegrationTasks.prototype = {
    initialize: function() {},

    createTasks: function() {
        var createdTasks = [];
        var processedProperties = []; // Track processed properties

        var propertyName = "onprem.integration.kpi";
        var integrationData = gs.getProperty(propertyName);

        if (!integrationData) {
            gs.error('❌ Sys Property "' + propertyName + '" is missing or empty.');
            return { error: "No integration data available" };
        }

        try {
            var integrations = JSON.parse(integrationData);

            for (var integration in integrations) {
                processedProperties.push(integration); // Track processed integrations
                gs.info('🔄 Processing Integration: ' + integration);

                var kpi = integrations[integration];

                if (!kpi.description || !kpi.recommendation) {
                    gs.error('⚠️ Missing required fields for integration: ' + JSON.stringify(kpi));
                    continue;
                }

                var existingTask = new GlideRecord('samp_sp_vb_task');
                existingTask.addQuery('short_description', kpi.description);
                existingTask.addEncodedQuery('stateNOT IN2,-5,3,7');
                existingTask.query();
                if (existingTask.next()) {
                    gs.info('✅ Task already exists for Integration: ' + kpi.description);
                    continue;
                }

                var taskGr = new GlideRecord('samp_sp_vb_task');
                taskGr.initialize();
                taskGr.setValue('name', integration);
                taskGr.setValue('short_description', kpi.description);
                taskGr.setValue('description', kpi.description);
                taskGr.setValue('instructions', kpi.recommendation);

                var taskId = taskGr.insert();
                if (taskId) {
                    gs.info('🚀 Created Task for: ' + integration + ' (Task ID: ' + taskId + ')');
                    createdTasks.push(integration);
                    gs.eventQueue('onprem.integration.task.created', taskGr, taskGr.sys_id);
                }
            }
        } catch (e) {
            gs.error('❌ Error processing sys_property "' + propertyName + '": ' + e.message);
        }

        return {
            createdTasks: createdTasks,
            processedProperties: processedProperties
        };
    },

    type: "CreateOnPremIntegrationTasks"
};
